{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "Launch Configuration has public IP address associated",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The resource explicitly sets associate_public_ip_address to true, which exposes the EC2 instance directly to the internet. This increases the attack surface and is generally discouraged unless strictly necessary for specific use cases not indicated here."
    }
  ],
  "patched_code": "resource "aws_launch_configuration" "lc" {
  name          = "test_ecs"
  image_id      = data.aws_ami.amazon_linux.id
  instance_type = "t2.micro"
  lifecycle {
    create_before_destroy = true
  }
  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name
  key_name                    = var.key_name
  security_groups             = [aws_security_group.ec2-sg.id]
  associate_public_ip_address = false
  user_data                   = <<EOF
sudo apt-get update
sudo echo "ECS_CLUSTER=${var.cluster_name}" >> /etc/ecs/ecs.config
EOF
}",
  "fix_summary": "Changed 'associate_public_ip_address' from true to false to prevent direct public exposure of the EC2 instances launched by this configuration."
}
